<template>
  <div class="space-tools-page space-y-5">
    <PageHeader :title="'空间工具'" :description="headerDescription" :breadcrumbs="breadcrumbs">
      <template #actions>
        <router-link class="tool-outline-button" to="/space/manage"><i class="fa fa-arrow-left"></i>空间列表</router-link>
        <router-link class="tool-outline-button" :to="spaceSettingsPath"><i class="fa fa-cog"></i>空间设置</router-link>
        <router-link class="tool-primary-button" to="/app/plugin-market"><i class="fa fa-plus"></i>添加工具</router-link>
      </template>
    </PageHeader>

    <section class="space-tools-hero">
      <div><p class="tool-eyebrow">SPACE AUTOMATION</p><h2>{{ spaceStore.currentSpaceName || '选择一个协作空间' }}</h2><p>{{ spaceStore.isPersonalSpace ? '默认个人空间不支持空间级共享工具。请切换到团队、企业或项目空间后继续。' : '在此管理当前空间安装的插件、可访问工作流与最近自动化执行。' }}</p><div class="space-tools-hero__actions"><router-link v-if="!spaceStore.isPersonalSpace" class="tool-hero-button" to="/app/plugin-market"><i class="fa fa-puzzle-piece"></i>浏览插件市场</router-link><router-link v-if="!spaceStore.isPersonalSpace" class="tool-hero-button tool-hero-button--subtle" to="/app/workflow-market"><i class="fa fa-random"></i>浏览工作流模板</router-link><router-link v-if="!spaceStore.isPersonalSpace" class="tool-hero-button tool-hero-button--subtle" to="/developer/workflows/new"><i class="fa fa-plus"></i>创建自动化</router-link></div></div>
      <aside><div><b>{{ spaceInstallations.length }}</b><span>空间插件</span></div><div><b>{{ spaceWorkflows.length }}</b><span>可访问工作流</span></div><div><b>{{ succeededExecutionCount }}</b><span>已成功执行</span></div></aside>
    </section>

    <section v-if="spaceStore.isPersonalSpace" class="tool-personal-state"><i class="fa fa-lock"></i><div><h2>当前是个人空间</h2><p>空间工具属于团队协作能力。你仍可在“我的插件”和“我的工作流”中管理个人资源，或前往空间管理创建团队/企业空间。</p></div><router-link to="/space/manage?create=1">创建协作空间</router-link></section>

    <template v-else>
      <section class="tools-toolbar"><nav role="tablist" aria-label="空间工具分区"><button v-for="tab in tabs" :key="tab.key" type="button" role="tab" :aria-selected="activeTab === tab.key" :class="{ active: activeTab === tab.key }" @click="setTab(tab.key)"><i :class="tab.icon"></i>{{ tab.label }}<small>{{ tab.count }}</small></button></nav><label><i class="fa fa-search"></i><input v-model.trim="toolQuery" placeholder="搜索当前空间的工具" /></label></section>

      <section v-if="loading" class="tool-grid tool-grid--skeleton"><article v-for="index in 6" :key="index"><span></span><span></span><span></span></article></section>
      <section v-else-if="error" class="tool-state tool-state--error"><i class="fa fa-exclamation-triangle"></i><h2>空间工具无法加载</h2><p>{{ error }}</p><button type="button" @click="loadAll">重新加载</button></section>

      <section v-else-if="activeTab === 'plugins'" class="tool-section"><div class="tool-section__heading"><div><p class="tool-eyebrow">INSTALLED PLUGINS</p><h2>已安装插件</h2><p>只显示当前空间范围的安装记录；开关和移除操作均继续通过插件服务进行授权。</p></div><router-link class="tool-text-link" to="/app/plugin-market">添加插件<i class="fa fa-arrow-right"></i></router-link></div><div v-if="filteredInstallations.length" class="tool-grid"><article v-for="item in filteredInstallations" :key="item.installationId" class="tool-card"><div class="tool-card__header"><span class="tool-icon" :class="item.pluginType === 'LOCAL_PLUGIN' ? 'is-local' : item.pluginType === 'WORKFLOW_PLUGIN' ? 'is-workflow' : ''"><i :class="pluginIcon(item.pluginType)"></i></span><div class="min-w-0 flex-1"><h3>{{ item.pluginName }}</h3><p>v{{ item.version }} · {{ pluginTypeLabel(item.pluginType) }}</p></div><span class="tool-status" :class="{ muted: !item.enabled }"><i :class="item.enabled ? 'fa fa-check-circle' : 'fa fa-pause-circle'"></i>{{ item.enabled ? '已启用' : '已停用' }}</span></div><div class="tool-card__data"><div><span>安装范围</span><b>当前空间</b></div><div><span>授予权限</span><b>{{ permissionCount(item) }} 项</b></div><div><span>安装时间</span><b>{{ formatDate(item.installedAt) }}</b></div></div><div class="tool-card__actions"><button type="button" class="tool-outline-button" @click="openPluginDetail(item)"><i class="fa fa-info-circle"></i>详情</button><label class="tool-toggle"><input type="checkbox" :checked="item.enabled" @change="togglePlugin(item, ($event.target as HTMLInputElement).checked)" /><span></span>{{ item.enabled ? '启用' : '停用' }}</label><button type="button" class="tool-icon-button tool-icon-button--danger" title="移除插件" @click="confirmRemove(item)"><i class="fa fa-trash-o"></i></button></div></article></div><div v-else class="tool-state"><i class="fa fa-puzzle-piece"></i><h2>当前空间还没有匹配的插件</h2><p>从插件市场安装后，空间管理员可在这里启用、停用或移除共享工具。</p><router-link to="/app/plugin-market">前往插件市场</router-link></div></section>

      <section v-else-if="activeTab === 'workflows'" class="tool-section"><div class="tool-section__heading"><div><p class="tool-eyebrow">WORKFLOWS</p><h2>可访问工作流</h2><p>此列表来自当前空间上下文的工作流 API，不把“可访问”误标为“已绑定”。</p></div><router-link class="tool-text-link" to="/app/workflow-market">导入模板<i class="fa fa-arrow-right"></i></router-link></div><div v-if="filteredWorkflows.length" class="tool-grid"><article v-for="workflow in filteredWorkflows" :key="workflow.workflowId" class="tool-card"><div class="tool-card__header"><span class="tool-icon is-workflow"><i class="fa fa-random"></i></span><div class="min-w-0 flex-1"><h3>{{ workflow.name }}</h3><p class="tool-mono">{{ workflow.slug }}</p></div><span class="tool-status" :class="{ muted: workflow.status !== 'ACTIVE' && workflow.status !== 'PUBLISHED' }">{{ workflow.status }}</span></div><p class="tool-description">{{ workflow.description || '暂无工作流说明。' }}</p><div class="tool-card__data"><div><span>归属范围</span><b>{{ workflow.ownerScopeType === 'SPACE' ? '空间' : '个人' }}</b></div><div><span>更新时间</span><b>{{ formatDate(workflow.updatedAt) }}</b></div><div><span>版本</span><b>{{ workflow.latestVersionId ? '已生成' : '未提供' }}</b></div></div><div class="tool-card__actions"><button type="button" class="tool-outline-button" @click="openWorkflow(workflow)"><i class="fa fa-pencil"></i>打开 IDE</button><button type="button" class="tool-run-button" :disabled="runningWorkflowId === workflow.workflowId" @click="runWorkflow(workflow)"><i :class="runningWorkflowId === workflow.workflowId ? 'fa fa-spinner fa-spin' : 'fa fa-play'"></i>{{ runningWorkflowId === workflow.workflowId ? '正在提交' : '运行' }}</button></div></article></div><div v-else class="tool-state"><i class="fa fa-random"></i><h2>当前上下文没有可访问工作流</h2><p>可从工作流模板市场导入，或创建一个属于当前空间的自动化流程。</p><router-link to="/app/workflow-market">浏览工作流市场</router-link></div></section>

      <section v-else-if="activeTab === 'automation'" class="tool-section"><div class="tool-section__heading"><div><p class="tool-eyebrow">RECENT EXECUTIONS</p><h2>自动化任务</h2><p>选择工作流后从现有执行历史接口加载；该页不会捏造全局执行成功率。</p></div><label class="tool-workflow-select">工作流<select v-model="selectedWorkflowId" @change="loadExecutions"><option value="">选择工作流</option><option v-for="workflow in spaceWorkflows" :key="workflow.workflowId" :value="workflow.workflowId">{{ workflow.name }}</option></select></label></div><div v-if="!selectedWorkflowId" class="tool-state"><i class="fa fa-list-alt"></i><h2>选择一个工作流以查看执行记录</h2><p>执行历史按当前空间上下文和所选工作流查询。</p></div><div v-else-if="executionLoading" class="execution-skeleton"><span v-for="index in 5" :key="index"></span></div><div v-else-if="executions.length" class="execution-list"><article v-for="execution in executions" :key="execution.executionId"><span class="execution-status" :class="execution.status.toLowerCase()"><i :class="executionIcon(execution.status)"></i></span><div class="min-w-0 flex-1"><h3>{{ execution.status }}</h3><p>{{ execution.currentStep || execution.errorSummary || '等待服务端更新执行摘要' }}</p><small>{{ execution.triggerType }} · {{ formatDate(execution.createdAt) }} · {{ execution.traceId ? `Trace ${execution.traceId}` : '无 Trace ID' }}</small></div><button v-if="execution.status === 'FAILED' || execution.status === 'TIMEOUT'" type="button" class="tool-outline-button" @click="retryExecution(execution.executionId)">重试</button></article></div><div v-else class="tool-state"><i class="fa fa-history"></i><h2>暂无执行记录</h2><p>可从“可访问工作流”页面手动运行，或在 IDE 中设置事件和定时触发器。</p></div></section>

      <section v-else class="tool-section"><div class="tool-section__heading"><div><p class="tool-eyebrow">TOOL MARKET</p><h2>为这个空间添加能力</h2><p>在市场选择已审核插件或自动化模板，再返回当前空间确认安装和运行状态。</p></div></div><div class="tool-market-cards"><router-link to="/app/plugin-market"><i class="fa fa-puzzle-piece"></i><div><h3>插件市场</h3><p>文件处理、数据转换、通知和客户端扩展。</p></div><i class="fa fa-arrow-right"></i></router-link><router-link to="/app/workflow-market"><i class="fa fa-random"></i><div><h3>工作流市场</h3><p>导入文件、AI、审批和定时自动化模板。</p></div><i class="fa fa-arrow-right"></i></router-link><router-link :to="spaceSettingsPath"><i class="fa fa-shield"></i><div><h3>空间权限</h3><p>在成员和设置页面调整工具管理边界。</p></div><i class="fa fa-arrow-right"></i></router-link></div></section>
    </template>

    <Teleport to="body"><div v-if="removingInstallation" class="tool-confirm-modal" @click.self="removingInstallation = null"><section><h2>移除空间插件</h2><p>确定从当前空间移除“{{ removingInstallation.pluginName }}”吗？此操作不会删除插件市场中的发布版本。</p><footer><button type="button" class="tool-outline-button" @click="removingInstallation = null">取消</button><button type="button" class="tool-danger-button" @click="removePlugin">确认移除</button></footer></section></div></Teleport>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import PageHeader from '@/components/common/PageHeader.vue'
import { listPluginInstallationsApi, setSpacePluginEnabledApi, uninstallSpacePluginApi, type PluginInstallation, type PluginType } from '@/api/modules/plugins'
import { listWorkflowExecutionsApi, listWorkflowsApi, retryWorkflowExecutionApi, runWorkflowApi, type WorkflowExecutionInfo, type WorkflowInfo } from '@/api/modules/workflows'
import { useSpaceStore } from '@/stores/spaceStore'
import { useToastStore } from '@/stores/toastStore'

const route = useRoute(); const router = useRouter(); const spaceStore = useSpaceStore(); const toast = useToastStore()
const installations = ref<PluginInstallation[]>([]); const workflows = ref<WorkflowInfo[]>([]); const executions = ref<WorkflowExecutionInfo[]>([])
const loading = ref(false); const error = ref(''); const activeTab = ref<'plugins' | 'workflows' | 'automation' | 'market'>('plugins'); const toolQuery = ref(''); const selectedWorkflowId = ref(''); const executionLoading = ref(false); const runningWorkflowId = ref(''); const removingInstallation = ref<PluginInstallation | null>(null)
const spaceInstallations = computed(() => installations.value.filter(item => item.scopeType === 'SPACE'))
const spaceWorkflows = computed(() => workflows.value.filter(item => item.ownerScopeType === 'SPACE' || item.ownerScopeId === spaceStore.currentSpaceId))
const filteredInstallations = computed(() => filterByToolQuery(spaceInstallations.value, item => `${item.pluginName} ${item.pluginType} ${item.version}`))
const filteredWorkflows = computed(() => filterByToolQuery(spaceWorkflows.value, item => `${item.name} ${item.slug} ${item.description || ''}`))
const succeededExecutionCount = computed(() => executions.value.filter(item => item.status === 'SUCCEEDED').length)
const headerDescription = computed(() => spaceStore.currentSpaceName ? `管理“${spaceStore.currentSpaceName}”的共享插件、工作流和执行记录` : '展示当前空间的插件、工作流与自动化任务')
const spaceSettingsPath = computed(() => spaceStore.currentSpaceId ? `/space/${encodeURIComponent(spaceStore.currentSpaceId)}/settings` : '/space/manage')
const breadcrumbs = computed(() => [{ label: '控制面板', to: '/app' }, { label: '空间管理', to: '/space/manage' }, { label: '空间工具' }])
const tabs = computed(() => [{ key: 'plugins' as const, label: '已安装插件', icon: 'fa fa-puzzle-piece', count: spaceInstallations.value.length }, { key: 'workflows' as const, label: '可访问工作流', icon: 'fa fa-random', count: spaceWorkflows.value.length }, { key: 'automation' as const, label: '自动化任务', icon: 'fa fa-history', count: executions.value.length }, { key: 'market' as const, label: '工具市场', icon: 'fa fa-shopping-bag', count: '' }])
function filterByToolQuery<T>(values: T[], read: (value: T) => string) { const term = toolQuery.value.toLocaleLowerCase(); return term ? values.filter(value => read(value).toLocaleLowerCase().includes(term)) : values }
function pluginIcon(type: PluginType) { return type === 'LOCAL_PLUGIN' ? 'fa fa-desktop' : type === 'WORKFLOW_PLUGIN' ? 'fa fa-random' : 'fa fa-cloud' }
function pluginTypeLabel(type: PluginType) { return type === 'LOCAL_PLUGIN' ? '本地扩展' : type === 'WORKFLOW_PLUGIN' ? '工作流插件' : '云插件' }
function permissionCount(item: PluginInstallation) { try { const parsed = JSON.parse(item.grantedPermissionsJson || '[]'); return Array.isArray(parsed) ? parsed.length : 0 } catch { return 0 } }
function formatDate(value?: string | null) { return value ? new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : '—' }
function executionIcon(status: string) { return status === 'SUCCEEDED' ? 'fa fa-check' : status === 'FAILED' || status === 'TIMEOUT' ? 'fa fa-exclamation' : status === 'RUNNING' ? 'fa fa-spinner fa-spin' : 'fa fa-clock-o' }
function setTab(tab: typeof activeTab.value) { activeTab.value = tab; void router.replace({ query: { ...route.query, tab } }) }
async function activateRouteSpace() {
  const targetSpaceId = typeof route.params.spaceId === 'string' ? route.params.spaceId : ''
  /* [REQ-SPACE-TOOLS-9.2~9.7] 独立空间工具路由必须切换 SDK 的 X-Space-Id 上下文，避免页面展示 A 空间而请求落在上一次选择的 B 空间。 */
  if (targetSpaceId && targetSpaceId !== spaceStore.currentSpaceId) await spaceStore.switchSpace(targetSpaceId)
}
async function loadAll() {
  if (spaceStore.isPersonalSpace) return
  loading.value = true; error.value = ''
  try { const [pluginResponse, workflowResponse] = await Promise.all([listPluginInstallationsApi(), listWorkflowsApi()]); installations.value = pluginResponse.data || []; workflows.value = workflowResponse.data || []; if (!selectedWorkflowId.value && spaceWorkflows.value[0]) { selectedWorkflowId.value = spaceWorkflows.value[0].workflowId; await loadExecutions() } }
  catch (cause: unknown) { error.value = cause instanceof Error ? cause.message : '空间工具请求失败，请稍后重试。'; installations.value = []; workflows.value = [] }
  finally { loading.value = false }
}
async function togglePlugin(item: PluginInstallation, enabled: boolean) { try { await setSpacePluginEnabledApi(item.installationId, enabled); item.enabled = enabled; toast.showToast(enabled ? '空间插件已启用' : '空间插件已停用', 'success') } catch (cause: unknown) { toast.showToast(cause instanceof Error ? cause.message : '更新插件状态失败', 'error'); await loadAll() } }
function confirmRemove(item: PluginInstallation) { removingInstallation.value = item }
async function removePlugin() { if (!removingInstallation.value) return; try { await uninstallSpacePluginApi(removingInstallation.value.installationId); installations.value = installations.value.filter(item => item.installationId !== removingInstallation.value?.installationId); toast.showToast('空间插件已移除', 'success') } catch (cause: unknown) { toast.showToast(cause instanceof Error ? cause.message : '移除插件失败', 'error') } finally { removingInstallation.value = null } }
function openPluginDetail(item: PluginInstallation) { void router.push(`/developer/marketplace/plugins/${encodeURIComponent(item.pluginId)}`) }
function openWorkflow(workflow: WorkflowInfo) { void router.push(`/app/workflows/${encodeURIComponent(workflow.workflowId)}/edit`) }
async function runWorkflow(workflow: WorkflowInfo) { runningWorkflowId.value = workflow.workflowId; try { await runWorkflowApi(workflow.workflowId); toast.showToast('工作流运行已提交', 'success'); selectedWorkflowId.value = workflow.workflowId; await loadExecutions(); activeTab.value = 'automation' } catch (cause: unknown) { toast.showToast(cause instanceof Error ? cause.message : '工作流运行提交失败', 'error') } finally { runningWorkflowId.value = '' } }
async function loadExecutions() { if (!selectedWorkflowId.value) { executions.value = []; return }; executionLoading.value = true; try { const response = await listWorkflowExecutionsApi(selectedWorkflowId.value, { page: 1, size: 30 }); executions.value = response.data || [] } catch (cause: unknown) { executions.value = []; toast.showToast(cause instanceof Error ? cause.message : '执行历史加载失败', 'error') } finally { executionLoading.value = false } }
async function retryExecution(executionId: string) { try { await retryWorkflowExecutionApi(executionId); toast.showToast('重试请求已提交', 'success'); await loadExecutions() } catch (cause: unknown) { toast.showToast(cause instanceof Error ? cause.message : '重试提交失败', 'error') } }
watch(() => route.query.tab, value => { activeTab.value = ['workflows', 'automation', 'market'].includes(String(value)) ? value as typeof activeTab.value : 'plugins' }, { immediate: true })
watch(() => spaceStore.currentSpaceId, () => { void loadAll() })
onMounted(async () => { await activateRouteSpace(); await loadAll() })
</script>

<style scoped>
.tool-outline-button,.tool-primary-button,.tool-danger-button { @apply inline-flex min-h-9 items-center gap-2 rounded-lg px-3 text-sm font-semibold transition; }.tool-outline-button { @apply border border-neutral-200 bg-white text-neutral-600 hover:border-primary hover:text-primary; }.tool-primary-button { @apply bg-primary text-white hover:bg-primary/90; }.tool-danger-button { @apply bg-red-600 text-white hover:bg-red-700; }.space-tools-hero { display:grid;gap:20px;overflow:hidden;border:1px solid #c4b5fd;border-radius:18px;background:radial-gradient(circle at 90% 12%,rgba(196,181,253,.55),transparent 31%),linear-gradient(135deg,#f5f3ff,#fff 62%,#eff6ff);padding:26px; }.tool-eyebrow { margin:0;color:#6d28d9;font-size:11px;font-weight:800;letter-spacing:.15em; }.space-tools-hero h2 { margin:7px 0 0;color:#1f2328;font-size:26px;letter-spacing:-.02em; }.space-tools-hero>div>p:not(.tool-eyebrow) { max-width:650px;margin:8px 0 0;color:#57606a;font-size:13px;line-height:1.7; }.space-tools-hero__actions { display:flex;flex-wrap:wrap;gap:8px;margin-top:18px; }.tool-hero-button { display:inline-flex;min-height:34px;align-items:center;gap:6px;border:1px solid #6d28d9;border-radius:6px;background:#6d28d9;padding:0 10px;color:#fff;font-size:12px;font-weight:700; }.tool-hero-button:hover { background:#5b21b6; }.tool-hero-button--subtle { border-color:#d0d7de;background:#fff;color:#57606a; }.tool-hero-button--subtle:hover { border-color:#6d28d9;background:#f5f3ff;color:#6d28d9; }.space-tools-hero>aside { display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-content:center;border:1px solid #d0d7de;border-radius:10px;background:rgba(255,255,255,.75);padding:12px; }.space-tools-hero>aside div { min-width:0;border-right:1px solid #d8dee4;padding:7px;text-align:center; }.space-tools-hero>aside div:last-child { border-right:0; }.space-tools-hero>aside b,.space-tools-hero>aside span { display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap; }.space-tools-hero>aside b { color:#24292f;font-size:18px; }.space-tools-hero>aside span { margin-top:3px;color:#57606a;font-size:10px; }.tool-personal-state { display:flex;align-items:center;gap:14px;border:1px solid #fcd34d;border-radius:10px;background:#fffbeb;padding:18px;color:#92400e; }.tool-personal-state>i { font-size:25px; }.tool-personal-state h2 { margin:0;font-size:15px; }.tool-personal-state p { margin:4px 0 0;font-size:12px;line-height:1.6; }.tool-personal-state>a { margin-left:auto;border:1px solid #f59e0b;border-radius:6px;background:#fff;padding:7px 10px;color:#92400e;font-size:12px;font-weight:700;white-space:nowrap; }.tools-toolbar { display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid #d0d7de; }.tools-toolbar nav { display:flex;overflow-x:auto; }.tools-toolbar nav button { display:inline-flex;align-items:center;gap:6px;border-bottom:2px solid transparent;padding:10px 11px;color:#57606a;font-size:12px;white-space:nowrap; }.tools-toolbar nav button:hover,.tools-toolbar nav button.active { border-bottom-color:#a78bfa;color:#24292f;font-weight:700; }.tools-toolbar nav small { border-radius:999px;background:#eaeef2;padding:1px 5px;color:#57606a;font-size:9px; }.tools-toolbar>label { display:flex;align-items:center;gap:6px;border:1px solid #d0d7de;border-radius:6px;background:#fff;padding:0 8px;color:#57606a; }.tools-toolbar>label:focus-within { border-color:#6d28d9;box-shadow:0 0 0 3px rgba(109,40,217,.13); }.tools-toolbar input { height:33px;width:220px;border:0;outline:0;background:transparent;color:#24292f;font-size:12px; }.tool-section { margin-top:28px; }.tool-section__heading { display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:14px; }.tool-section__heading h2 { margin:4px 0 0;color:#24292f;font-size:20px; }.tool-section__heading p { max-width:650px;margin:5px 0 0;color:#57606a;font-size:12px;line-height:1.6; }.tool-text-link { display:inline-flex;align-items:center;gap